steps.script:
var bw = GameState.get_unit("U_BATTLEWAGON_A")
bw["flags"].merge({"charged_this_turn": true, "fights_first": true}, true)
var p = bw.models[0].position
var xs = [-3.2, -1.6, 0.0, 1.6, 3.2]
var cg = GameState.get_unit("U_CUSTODIAN_GUARD_C")
for i in range(cg.models.size()):
	cg.models[i]["position"] = {"x": float(p.x) + xs[i] * 40.0, "y": float(p.y) + 4.55 * 40.0}
	cg.models[i]["wounds"] = 99
	cg.models[i]["current_wounds"] = 99
return RulesEngine.is_unit_engaged("U_BATTLEWAGON_A", GameState.state)

var p = PhaseManager.get_current_phase_instance()
var n = 0
var ok = true
for d in p.dice_log:
	if typeof(d) != TYPE_DICTIONARY or str(d.get("context", "")) != "hit_roll_melee":
		continue
	var w = str(d.get("weapon", ""))
	var prof = RulesEngine.get_weapon_profile(w)
	var araw = str(prof.get("attacks_raw", prof.get("attacks", 1)))
	if not araw.is_valid_int():
		continue
	var cx = RulesEngine.get_cleave_value(w)
	var new_cx = cx + 1 if cx > 0 else 1
	var expected = int(araw) + new_cx
	print("MOW scenario: %s A=%s cleave %d->%d dice=%d expected=%d" % [w, araw, cx, new_cx, int(d.get("total_attacks", -1)), expected])
	n += 1
	if int(d.get("total_attacks", -1)) != expected:
		ok = false
return n > 0 and ok
